() => {
  const results = [];
  // Find all restaurant items
  const links = document.querySelectorAll('a[aria-label]');
  for (const link of links) {
    const ariaLabel = link.getAttribute('aria-label');
    if (ariaLabel && !['Google 应用','登录'].includes(ariaLabel)) {
      const parent = link.closest('div');
      if (parent) {
        const textContent = parent.textContent;
        // Look for rating patterns
        const ratingMatch = textContent.match(/(\d+\.\d+)\s*[(（](\d+)[)）]/);
        if (ratingMatch) {
          results.push({name: ariaLabel, rating: ratingMatch[1], reviews: ratingMatch[2], allText: textContent.substring(0, 200)});
        } else {
          results.push({name: ariaLabel, rating: 'N/A', allText: textContent.substring(0, 200)});
        }
      }
    }
  }
  return results;
}

() => {
  const results = [];
  const links = document.querySelectorAll('a[aria-label]');
  for (const link of links) {
    const ariaLabel = link.getAttribute('aria-label');
    if (ariaLabel && ariaLabel.length > 3 && !['Google 应用','登录'].includes(ariaLabel)) {
      const grandparent = link.parentElement ? link.parentElement.parentElement : null;
      if (grandparent) {
        const textContent = grandparent.textContent;
        results.push({name: ariaLabel, text: textContent.substring(0, 300)});
      }
    }
  }
  return results;
}

() => {
  const buttons = document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === '评分' || btn.textContent.trim() === '价格') {
      btn.click();
      return 'clicked ' + btn.textContent.trim();
    }
  }
  return 'not found';
}

() => {
  const allText = document.body.innerText;
  // Extract potential rating values
  const ratingMatches = allText.match(/[0-9]\.[0-9]\s*\([0-9,]+\)/g);
  return {ratings: ratingMatches, allText: allText.substring(0, 3000)};
}

() => {
  const allText = document.body.innerText;
  // Find everything that looks like a rating followed by reviews
  const ratingMatches = allText.match(/[0-9]\.[0-9][^\n]*\([0-9,]+\)/g) || [];
  return JSON.stringify({ratings: ratingMatches.slice(0, 30), len: allText.length});
}

() => {
  // Find a close button or any element to dismiss overlay
  const closeBtns = document.querySelectorAll('button');
  for (const btn of closeBtns) {
    if (btn.getAttribute('aria-label') === '关闭') {
      btn.click();
      return 'clicked close';
    }
  }
  return 'no close button found';
}

() => {
  // Try to find the score/rating element
  const results = document.querySelectorAll('[aria-label]');
  for (const el of results) {
    const label = el.getAttribute('aria-label');
    if (label && label.includes('评分')) {
      return {found: label};
    }
  }
  // Look for restaurant items
  const links = document.querySelectorAll('a[aria-label]');
  const items = [];
  for (const link of links) {
    const label = link.getAttribute('aria-label');
    if (label && label.length > 3 && label.length < 100 && !['登录','Google 应用'].includes(label)) {
      const parent = link.parentElement;
      const grandparent = parent ? parent.parentElement : null;
      const text = grandparent ? grandparent.innerText.substring(0, 600) : '';
      items.push({name: label, text: text});
    }
  }
  return {items: items.slice(0, 15)};
}

