() => {
  // Look for the overlay and find a way to close it
  const overlay = document.querySelector('.m6QErb.D6yfnc');
  if (overlay) {
    const closeBtn = overlay.querySelector('button[aria-label="关闭"]');
    if (closeBtn) {
      closeBtn.click();
      return 'clicked overlay close';
    }
  }
  // Try clicking anywhere outside the overlay
  return 'tried to close';
}

() => {
  // Find all overlay divs
  const overlays = document.querySelectorAll('div.m6QErb.D6yfnc');
  for (const overlay of overlays) {
    if (overlay.style.display !== 'none' && overlay.offsetParent !== null) {
      // Find close button
      const closeBtn = overlay.querySelector('button[aria-label="关闭"]');
      if (closeBtn) {
        closeBtn.click();
        return {clicked: 'closed overlay', count: overlays.length};
      }
    }
  }
  return {clicked: 'no overlay found', count: overlays.length};
}

() => {
  // Look for the actual overlay with text "You haven't downloaded..."
  const allDivs = document.querySelectorAll('div');
  for (const div of allDivs) {
    const txt = div.innerText || '';
    if (txt.includes('充分利用 Google 地图') && div.querySelector('button[aria-label="关闭"]')) {
      const closeBtn = div.querySelector('button[aria-label="关闭"]');
      closeBtn.click();
      return 'clicked';
    }
  }
  // Try just dispatching Escape
  document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape'}));
  return 'tried escape';
}

() => {
  // Get the full HTML of all restaurant items
  const items = document.querySelectorAll('a[aria-label]');
  const results = [];
  for (const item of items) {
    const label = item.getAttribute('aria-label');
    if (['Boston Sail Loft', 'Yankee Lobster', 'Atlantic Fish Company', "Luke's Lobster Back Bay", 'Boston Lobster & Seafood', 'James Hook & Co', '粤唯鲜'].includes(label)) {
      results.push({name: label, html: item.parentElement.parentElement.innerHTML.substring(0, 1000)});
    }
  }
  return JSON.stringify(results);
}

() => {
  // Create a hidden div with the result
  const items = document.querySelectorAll('a[aria-label]');
  const results = [];
  for (const item of items) {
    const label = item.getAttribute('aria-label');
    if (['Boston Sail Loft', 'Yankee Lobster', 'Atlantic Fish Company', "Luke's Lobster Back Bay", 'Boston Lobster & Seafood', 'James Hook & Co', '粤唯鲜'].includes(label)) {
      const html = item.parentElement.parentElement.innerHTML;
      // Get stars via aria-label
      const starEl = item.parentElement.parentElement.querySelector('[role="img"][aria-label]');
      const starLabel = starEl ? starEl.getAttribute('aria-label') : '';
      results.push(label + ': ' + starLabel);
    }
  }
  // Find ratings using regex
  const allHTML = document.querySelector('.m6QErb.D6yfnc') ? document.querySelector('.m6QErb.D6yfnc').innerHTML : document.body.innerHTML;
  const ratingMatches = allHTML.match(/(?:aria-label|aria-label=\")(\d+\.\d+ ?stars?[^"]{0,30})/g) || [];
  return 'ratings found: ' + ratingMatches.length + ' | ' + results.join(' | ');
}

() => {
  // Get all restaurant items by looking at the result list
  const places = document.querySelectorAll('.m6QErb.D6yfnc > div');
  const result = [];
  for (const place of places) {
    const nameEl = place.querySelector('.NrDZNb') || place.querySelector('.qBF1Pd') || place.querySelector('.fontHeadlineSmall');
    const ratingEl = place.querySelector('[role="img"]');
    const name = nameEl ? nameEl.textContent : '';
    const ariaRating = ratingEl ? ratingEl.getAttribute('aria-label') : '';
    if (name) {
      result.push(name + ' :: ' + ariaRating);
    }
  }
  // Write results to an element we can see
  let out = document.querySelector('#_extracted_data');
  if (!out) {
    out = document.createElement('div');
    out.id = '_extracted_data';
    out.style.position = 'fixed';
    out.style.top = '0';
    out.style.left = '0';
    out.style.zIndex = '999999';
    out.style.background = 'yellow';
    out.style.padding = '20px';
    document.body.appendChild(out);
  }
  out.textContent = result.join('\n');
  return JSON.stringify(result);
}

